function mockFetch(ms, wartosc) {
  return new Promise((resolve) =>
    setTimeout(() => resolve({ ok: true, status: 200, json: () => Promise.resolve(wartosc) }), ms)
  );
}
async function pobierzWiele() {
  const odpowiedzi = await Promise.all([mockFetch(100, "a"), mockFetch(50, "b"), mockFetch(150, "c")]);
  const dane = await Promise.all(odpowiedzi.map((odp) => odp.json()));
  console.log(dane);
}
pobierzWiele(); // ["a", "b", "c"] - zachowana kolejnosc przekazania

function fetchSukces() {
  return Promise.resolve({ ok: true, status: 200, json: () => Promise.resolve({ wynik: "gotowe" }) });
}
async function pobierzJson(fetchFn) {
  try {
    const odpowiedz = await fetchFn();
    if (!odpowiedz.ok) throw new Error("HTTP " + odpowiedz.status);
    return await odpowiedz.json();
  } catch (err) {
    if (err instanceof TypeError) throw new Error("Problem z siecia: " + err.message);
    throw err;
  }
}
pobierzJson(fetchSukces).then((w) => console.log(w)); // { wynik: "gotowe" }

