async function pobierzZPonawianiem(fetchFn, maxProb) {
  for (let proba = 1; proba <= maxProb; proba++) {
    try {
      return await fetchFn();
    } catch (err) {
      if (!(err instanceof TypeError) || proba === maxProb) throw err;
    }
  }
}
let licznik = 0;
function niestabilnyFetch() {
  licznik++;
  if (licznik < 3) return Promise.reject(new TypeError("chwilowy brak sieci"));
  return Promise.resolve({ ok: true, status: 200 });
}
pobierzZPonawianiem(niestabilnyFetch, 5).then((odp) => console.log(odp.status, "licznik:", licznik));
// 200 licznik: 3

async function pobierzZDomyslna(fetchFn, wartoscDomyslna) {
  try {
    const odpowiedz = await fetchFn();
    if (!odpowiedz.ok) throw new Error("HTTP " + odpowiedz.status);
    return await odpowiedz.json();
  } catch (err) {
    return wartoscDomyslna;
  }
}
function fetchZly() {
  return Promise.reject(new TypeError("brak sieci"));
}
pobierzZDomyslna(fetchZly, { dane: "domyslne" }).then((w) => console.log(w));
// { dane: "domyslne" }

// Prawdziwy fetch() wysyla RZECZYWISTE zapytanie HTTP do serwera -
// wymaga dzialajacego polaczenia sieciowego, a jego wynik zalezy od
// zewnetrznego serwera (moze sie zmienic, moze byc wolny, moze
// chwilowo nie dzialac). Do celow tej lekcji (i automatycznej
// weryfikacji poprawnosci przykladow) uzywane sa WLASNE, lokalne
// funkcje o nazwie fetch/mockFetch, ktore symuluja dokladnie ten sam
// KONTRAKT (Promise<Response> z ok/status/json()), ale w pelni
// deterministyczny i dzialajacy bez sieci - mechanika (dwa await,
// sprawdzenie ok, TypeError vs Error) jest identyczna jak z prawdziwym
// fetch, tylko dane sa z gory znane i powtarzalne.
console.log("mock fetch pozwala przetestowac dokladnie te sama mechanike bez sieci");

